"""Tests for the Android release-signing helpers in mobile/app/tool."""
from __future__ import annotations

import base64
import importlib.util
import os
import stat
import subprocess
from pathlib import Path

import pytest

TOOL = Path(__file__).resolve().parents[1] / "mobile" / "tool"
_spec = importlib.util.spec_from_file_location("signing", TOOL / "configure-android-signing.py")
signing = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(signing)

# app/build.gradle.kts as generated by `flutter create` (stable template).
FLUTTER_TEMPLATE = """plugins {
    id("com.android.application")
    // The Flutter Gradle Plugin must be applied after the Android and Kotlin Gradle plugins.
    id("dev.flutter.flutter-gradle-plugin")
}

android {
    namespace = "io.github.uekala.ladecockpit"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = flutter.ndkVersion

    defaultConfig {
        applicationId = "io.github.uekala.ladecockpit"
        minSdk = flutter.minSdkVersion
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
    }

    buildTypes {
        release {
            // TODO: Add your own signing config for the release build.
            // Signing with the debug keys for now, so `flutter run --release` works.
            signingConfig = signingConfigs.getByName("debug")
        }
    }
}

flutter {
    source = "../.."
}
"""

KEYSTORE = base64.b64encode(b"\xfe\xed\xfe\xed" + b"k" * 200).decode()
SECRETS = {
    "ANDROID_KEYSTORE_BASE64": KEYSTORE,
    "ANDROID_KEYSTORE_PASSWORD": "store-pass",
    "ANDROID_KEY_ALIAS": "upload",
    "ANDROID_KEY_PASSWORD": "key-pass",
}


def _app(tmp_path: Path) -> Path:
    gradle = tmp_path / "android" / "app" / "build.gradle.kts"
    gradle.parent.mkdir(parents=True)
    gradle.write_text(FLUTTER_TEMPLATE, encoding="utf-8")
    return tmp_path


def test_release_build_uses_persistent_key(tmp_path):
    app = _app(tmp_path)
    assert signing.configure(app, SECRETS, required=True) is True

    gradle = (app / "android" / "app" / "build.gradle.kts").read_text(encoding="utf-8")
    assert 'signingConfig = signingConfigs.getByName("release")' in gradle
    assert 'getByName("debug")' not in gradle
    assert gradle.index("signingConfigs {") < gradle.index("buildTypes {")
    assert 'System.getenv("ANDROID_KEYSTORE_PASSWORD")' in gradle
    # Passwords never end up in a file.
    assert "store-pass" not in gradle and "key-pass" not in gradle
    assert not (app / "android" / "key.properties").exists()

    keystore = app / "android" / "app" / "release-upload.jks"
    assert keystore.read_bytes() == base64.b64decode(KEYSTORE)
    assert stat.S_IMODE(os.stat(keystore).st_mode) == 0o600


def test_patch_is_idempotent(tmp_path):
    once = signing.patch_gradle(FLUTTER_TEMPLATE)
    assert signing.patch_gradle(once) == once
    assert once.count('create("release")') == 1


def test_missing_secrets_skip_unless_required(tmp_path, capsys):
    app = _app(tmp_path)
    assert signing.configure(app, {}, required=False) is False
    assert "Kein Release-Schlüssel" in capsys.readouterr().out
    assert 'getByName("debug")' in (app / "android" / "app" / "build.gradle.kts").read_text()

    with pytest.raises(signing.SigningError, match="ANDROID_KEY_ALIAS"):
        signing.configure(app, {**SECRETS, "ANDROID_KEY_ALIAS": ""}, required=True)


def test_invalid_keystore_is_rejected(tmp_path):
    app = _app(tmp_path)
    with pytest.raises(signing.SigningError, match="Base64"):
        signing.configure(app, {**SECRETS, "ANDROID_KEYSTORE_BASE64": "%%%"}, required=True)
    with pytest.raises(signing.SigningError, match="keinen Keystore"):
        signing.configure(
            app, {**SECRETS, "ANDROID_KEYSTORE_BASE64": base64.b64encode(b"x").decode()}, True
        )


def test_unknown_gradle_layout_fails_loudly(tmp_path):
    with pytest.raises(signing.SigningError):
        signing.patch_gradle("plugins {}\n")


def test_command_line_exit_codes(tmp_path):
    app = _app(tmp_path)
    script = TOOL / "configure-android-signing.py"
    env = {k: v for k, v in os.environ.items() if not k.startswith("ANDROID_KEY")}
    missing = subprocess.run(
        ["python3", str(script), "--required", "--app-dir", str(app)],
        env=env, capture_output=True, text=True, check=False,
    )
    assert missing.returncode == 1
    assert "::error::" in missing.stderr
    output = tmp_path / "github_output"
    skipped = subprocess.run(
        ["python3", str(script), "--app-dir", str(app)],
        env={**env, "GITHUB_OUTPUT": str(output)}, capture_output=True, text=True, check=False,
    )
    assert skipped.returncode == 0
    assert output.read_text() == "signed=false\n"
    ok = subprocess.run(
        ["python3", str(script), "--required", "--app-dir", str(app)],
        env={**env, **SECRETS, "GITHUB_OUTPUT": str(output)},
        capture_output=True, text=True, check=False,
    )
    assert ok.returncode == 0, ok.stderr
    assert output.read_text().endswith("signed=true\n")


def _fake_apksigner(tmp_path: Path, subject: str, digest: str) -> dict[str, str]:
    tools = tmp_path / "sdk" / "build-tools" / "36.0.0"
    tools.mkdir(parents=True)
    fake = tools / "apksigner"
    fake.write_text(
        "#!/usr/bin/env bash\n"
        'if [[ "$2" == "--print-certs" ]]; then\n'
        f'  echo "Signer #1 certificate DN: {subject}"\n'
        f'  echo "Signer #1 certificate SHA-256 digest: {digest}"\n'
        "fi\n",
        encoding="utf-8",
    )
    fake.chmod(0o755)
    return {"ANDROID_HOME": str(tmp_path / "sdk"), "PATH": os.environ["PATH"]}


def _verify(env: dict[str, str]) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["bash", str(TOOL / "verify-apk-signature.sh"), "app.apk"],
        env=env, capture_output=True, text=True, check=False,
    )


def test_verify_accepts_expected_certificate(tmp_path):
    env = _fake_apksigner(tmp_path, "CN=Ladecockpit", "ab:cd:ef")
    result = _verify({**env, "ANDROID_SIGNING_CERT_SHA256": "AB:CD:EF"})
    assert result.returncode == 0, result.stdout + result.stderr
    assert "SHA-256: ABCDEF" in result.stdout


def test_verify_rejects_other_certificate_and_debug_key(tmp_path):
    env = _fake_apksigner(tmp_path, "CN=Ladecockpit", "abcdef")
    assert _verify({**env, "ANDROID_SIGNING_CERT_SHA256": "123456"}).returncode == 1
    debug_env = _fake_apksigner(tmp_path / "debug", "C=US, O=Android, CN=Android Debug", "aa")
    result = _verify(debug_env)
    assert result.returncode == 1
    assert "Debug-Schlüssel" in result.stdout


@pytest.mark.parametrize("script", sorted(TOOL.glob("*.sh")), ids=lambda p: p.name)
def test_shell_scripts_parse(script: Path) -> None:
    subprocess.run(["bash", "-n", str(script)], check=True)


def _stub(bin_dir: Path, name: str, body: str) -> None:
    path = bin_dir / name
    path.write_text("#!/usr/bin/env bash\n" + body, encoding="utf-8")
    path.chmod(path.stat().st_mode | stat.S_IXUSR)


def _run_setup(tmp_path: Path, secret_list: str, list_rc: int = 0) -> subprocess.CompletedProcess:
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    _stub(bin_dir, "keytool", "exit 99\n")
    _stub(bin_dir, "gh", (
        'if [[ "$1 $2" == "secret list" ]]; then\n'
        f"  printf '%b' {secret_list!r}\n"
        f"  exit {list_rc}\n"
        "fi\n"
        'if [[ "$1" == "secret" || "$1" == "variable" ]]; then echo WROTE >> "$GH_LOG"; fi\n'
        "exit 0\n"
    ))
    env = {**os.environ, "PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}",
           "GH_LOG": str(tmp_path / "gh.log")}
    return subprocess.run(["bash", str(TOOL / "setup-android-signing.sh"), "owner/repo"],
                          cwd=tmp_path, env=env, input="", capture_output=True, text=True)


def test_setup_refuses_when_key_already_exists(tmp_path: Path) -> None:
    result = _run_setup(tmp_path, "ANDROID_KEY_ALIAS\t2026-11-11\nANDROID_KEYSTORE_BASE64\t2026-11-11\n")
    assert result.returncode != 0
    assert "bereits einen Signaturschlüssel" in result.stderr
    assert not (tmp_path / "gh.log").exists()


def test_setup_stops_when_secret_list_fails(tmp_path: Path) -> None:
    result = _run_setup(tmp_path, "", list_rc=1)
    assert result.returncode != 0
    assert "nicht sicher abgefragt" in result.stderr
    assert not (tmp_path / "gh.log").exists()
